        // Fire click handlers during the bubble phase.
        DispatchPhase::Bubble => {
            if let Some(mouse_down) = captured_mouse_down.take() {
                let btn = mouse_down.button;

                let mouse_click = ClickEvent::Mouse(MouseClickEvent {
                    down: mouse_down,
                    up: event.clone(),
